// Some portions generated by Claude
package org.eclipse.rdf4j.opentelemetry.repository;

import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.rio.RDFHandler;
import org.eclipse.rdf4j.rio.RDFHandlerException;

/**
 * Wraps an {@link RDFHandler} to count the statements passed to it via {@link #getCount()}, without otherwise altering
 * its behaviour. Used to determine the number of statements returned by
 * {@code RepositoryConnection.exportStatements(...)}.
 */
class CountingRDFHandler implements RDFHandler {

	private final RDFHandler delegate;
	private long count = 0;

	CountingRDFHandler(RDFHandler delegate) {
		this.delegate = delegate;
	}

	long getCount() {
		return count;
	}

	@Override
	public void startRDF() throws RDFHandlerException {
		delegate.startRDF();
	}

	@Override
	public void endRDF() throws RDFHandlerException {
		delegate.endRDF();
	}

	@Override
	public void handleNamespace(String prefix, String uri) throws RDFHandlerException {
		delegate.handleNamespace(prefix, uri);
	}

	@Override
	public void handleStatement(Statement st) throws RDFHandlerException {
		delegate.handleStatement(st);
		count++;
	}

	@Override
	public void handleComment(String comment) throws RDFHandlerException {
		delegate.handleComment(comment);
	}
}
